-- Explicit SQL fixtures exercise admission/atomicity only; they are not a
-- claim of a real YouTube provider validation or playback.
insert into public.tenant_settings(tenant_id)values('10000000-0000-4000-8000-000000226201'),('10000000-0000-4000-8000-000000226202');
