 ('a0000000-0000-4000-8000-000000226201','10000000-0000-4000-8000-000000226201','abcdefghijk','Eigen gecontroleerde SQL-fixture','20000000-0000-4000-8000-000000226202','verified',true),
 ('a0000000-0000-4000-8000-000000226202','10000000-0000-4000-8000-000000226202','foreignvid1','Andere tenant SQL-fixture','20000000-0000-4000-8000-000000226203','verified',true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226201',true);
select lives_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000226201',(select value->'syncPresentation'from source_document))$$,'an owned verified Source video is admitted');
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000226201',jsonb_set((select value->'syncPresentation'from source_document),'{youtubeUrl}','"https://www.youtube.com/watch?v=foreignvid1"'))$$,'42501',null,'a foreign video cannot become an owned Source binding');
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000226201',jsonb_set((select value->'syncPresentation'from source_document),'{youtubeUrl}','"https://www.youtube.com/watch?v=unverified1"'))$$,'42501',null,'a syntactically valid URL is not provider validation');
update public.youtube_sources set validation_status='error'where id='a0000000-0000-4000-8000-000000226201';
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000226201',(select value->'syncPresentation'from source_document))$$,'42501',null,'failed provider validation closes authoring admission');
update public.youtube_sources set validation_status='verified'where id='a0000000-0000-4000-8000-000000226201';
select is(has_function_privilege('authenticated','private.sync_youtube_source_id_v1(uuid,text)','execute'),false,'the privileged resolver is private');
select is(has_function_privilege('authenticated','private.assert_sync_slide_before_youtube_v1(uuid,jsonb)','execute'),false,'the prior validator cannot bypass source binding');
select is(has_function_privilege('anon','private.assert_sync_youtube_release_binding_v1()','execute'),false,'anonymous callers cannot materialize a release');
grant select on source_document to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226201',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000226201","role":"authenticated","aal":"aal2"}',true);
create function pg_temp.source_youtube_batch()returns jsonb language sql immutable as $$select '[{"operation":"add_youtube","clientId":"b0000000-0000-4000-8000-000000226201","sourceId":"a0000000-0000-4000-8000-000000226201","durationSeconds":5},{"operation":"replace_fallback","itemId":"b0000000-0000-4000-8000-000000226201","mediaAssetId":"20000000-0000-4000-8000-000000226201","sourceKind":"youtube","sourceId":"a0000000-0000-4000-8000-000000226201"}]'::jsonb$$;
select lives_ok($$select public.mutate_playlist_batch_v1('70000000-0000-4000-8000-000000226201',0,pg_temp.source_youtube_batch(),'c0000000-0000-4000-8000-000000226201')$$,'one atomic existing batch binds the source and its complete Source MP4 fallback');
select is((select count(*)from public.playlist_items where playlist_id='70000000-0000-4000-8000-000000226201'),1::bigint,'one placement is stored');
select is((select media_asset_id from public.playlist_items where playlist_id='70000000-0000-4000-8000-000000226201'),'20000000-0000-4000-8000-000000226201'::uuid,'the placement owns the verified Source fallback');
select is((select fallback_media_asset_id from public.youtube_sources where id='a0000000-0000-4000-8000-000000226201'),'20000000-0000-4000-8000-000000226202'::uuid,'the original YouTube source fallback is preserved');
select lives_ok($$select public.mutate_playlist_batch_v1('70000000-0000-4000-8000-000000226201',0,pg_temp.source_youtube_batch(),'c0000000-0000-4000-8000-000000226201')$$,'the original batch receipt replays after the revision advances');
select is((select count(*)from public.playlist_items where playlist_id='70000000-0000-4000-8000-000000226201'),1::bigint,'receipt replay creates no duplicate');
select is((select count(*)from public.youtube_sources where tenant_id='10000000-0000-4000-8000-000000226202'),0::bigint,'cross-tenant YouTube rows stay unreadable');
reset role;
create function pg_temp.publish_source_youtube(p_item uuid,p_source uuid)returns void language sql as $$
 insert into public.playlist_release_items(id,tenant_id,playlist_id,release_id,media_asset_id,media_variant_id,sort_order,duration_seconds,fit_mode,muted,asset_kind,asset_title,storage_path,mime_type,file_size_bytes,checksum_sha256,source_item_id)
 select p_item,'10000000-0000-4000-8000-000000226201','70000000-0000-4000-8000-000000226201','80000000-0000-4000-8000-000000226201',asset.id,variant.id,0,5,'contain',true,asset.kind,asset.title,variant.storage_path,variant.mime_type,variant.file_size_bytes,variant.checksum_sha256,(select id from public.playlist_items where tenant_id=asset.tenant_id and playlist_id='70000000-0000-4000-8000-000000226201'and youtube_source_id is not distinct from p_source limit 1)
 from public.media_assets asset join public.media_variants variant on variant.tenant_id=asset.tenant_id and variant.asset_id=asset.id and variant.variant_type='player_1080p'
 where asset.id='20000000-0000-4000-8000-000000226201'and asset.tenant_id='10000000-0000-4000-8000-000000226201';
$$;
select lives_ok($$select pg_temp.publish_source_youtube('d0000000-0000-4000-8000-000000226201','a0000000-0000-4000-8000-000000226201')$$,'immutable materialization retains the verified matching Source and online video');
select is((select youtube_video_id from public.playlist_release_items where id='d0000000-0000-4000-8000-000000226201'),'abcdefghijk','the existing materializer freezes the real source video');
select is((select sync_studio_presentation_json->>'youtubeUrl'from public.playlist_release_items where id='d0000000-0000-4000-8000-000000226201'),'https://www.youtube.com/watch?v=abcdefghijk','the full Source fallback freezes the same canonical binding');
insert into public.playlist_items(tenant_id,playlist_id,media_asset_id,sort_order,duration_seconds)values('10000000-0000-4000-8000-000000226201','70000000-0000-4000-8000-000000226201','20000000-0000-4000-8000-000000226201',1,5);
select throws_ok($$select pg_temp.publish_source_youtube('d0000000-0000-4000-8000-000000226202',null)$$,'23514',null,'a Source video cannot be published through a static binding bypass');
insert into public.youtube_sources(id,tenant_id,video_id,title,fallback_media_asset_id,validation_status,embeddable)values('a0000000-0000-4000-8000-000000226203','10000000-0000-4000-8000-000000226201','zzzzzzzzzzz','Andere eigen SQL-fixture','20000000-0000-4000-8000-000000226202','verified',true);
insert into public.playlist_items(tenant_id,playlist_id,media_asset_id,youtube_source_id,sort_order,duration_seconds)values('10000000-0000-4000-8000-000000226201','70000000-0000-4000-8000-000000226201','20000000-0000-4000-8000-000000226201','a0000000-0000-4000-8000-000000226203',2,5);
select throws_ok($$select pg_temp.publish_source_youtube('d0000000-0000-4000-8000-000000226203','a0000000-0000-4000-8000-000000226203')$$,'23514',null,'a complete Source fallback cannot be attached to a different verified video');
update public.tenant_feature_flags set enabled=false where tenant_id='10000000-0000-4000-8000-000000226201'and flag_key='youtube_integration';
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000226201',(select value->'syncPresentation'from source_document))$$,'42501',null,'the existing rollout flag gates Source admission');
select *from finish();rollback;
